import{z as r,x as i,o as n,c as d,q as B,j as t,D as o,d as a,s,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"汇率脱节之谜","description":"","frontmatter":{"title":"汇率脱节之谜","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/exchange-rate-disconnect.md","filePath":"econ/exchange-rate-disconnect.md","lastUpdated":1791413859000}'),f={name:"econ/exchange-rate-disconnect.md"};function p(c,E,P,D,m,h){const A=i("Mermaid");return n(),d("div",null,[E[2]||(E[2]=B('<h1 id="汇率脱节之谜" tabindex="-1">汇率脱节之谜 <a class="header-anchor" href="#汇率脱节之谜" aria-label="Permalink to &quot;汇率脱节之谜&quot;">​</a></h1><div class="epigraph"><p>宏观基本面——货币、产出、利率——解释不了汇率的短期波动；随机游走往往胜过结构模型，这叫脱节，不是再估一条 PPP。</p><footer>—— Meese and Rogoff, Empirical Exchange Rate Models of the Seventies, JIE 1983；Obstfeld and Rogoff, The Six Major Puzzles in International Macroeconomics, NBER Macro Annual 2000</footer></div><p><a href="/econ/fx-intervention-reserves">上一课</a>把官方放进外汇市场。本课缺口是私人价格：名义与实际汇率与宏观变量短期几乎脱节。远期溢价下一课把资产平价的偏差写细。本课钉 Meese–Rogoff 与 Obstfeld–Rogoff 谜族，不重写<a href="/econ/uip-and-cip">UIP</a> 定义，不进限价簿。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Meese–Rogoff：用事后才知道的基本面代入 1970 年代结构模型，样本外汇预报仍打不赢随机游走。Obstfeld–Rogoff 六谜：贸易主乡偏好、股权组合主乡偏好、FH、PPP 偏离持久、Backus–Smith、汇率波动过大。脱节是波动与预报：宏观慢、\\(E\\) 快。缺口不是再讲超调代数——<a href="/econ/dornbusch-overshoot">Dornbusch</a> 已经给粘性价格下的超调；谜是定量上 \\(E\\) 比能合理化的基本面波动大得多，且预报无用。</p><p><span class="marginnote">Engel–West：若基本面近单位根、贴现因子近 1，汇率可以近似随机游走而仍是现值。脱节可以是「贴现的资产价格」，不必是非理性。定量是否够，仍争。</span></p><p><span class="marginnote">直觉类比：脱节像股价与季报的关系——公司营收按季度公布、动得慢，股价却随每一条新闻随时跳。汇率是「两国货币的比价」，宏观基本面就是那份季报：数字出得慢，价格等不及，于是短期走势和基本面图表对不上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预报评估用<a href="/econ/forecast-evaluation-dm">DM</a>：结构模型 vs 游走，损失平方。样本外才算。微观结构（Evans–Lyons 订单流）解释高频，本栏不写簿，只标：高频与宏观脱节可以分层。贸易成本（Obstfeld–Rogoff 对六谜的候选）用分割货物市场解释 PPP 与波动，但是否一块石头打六鸟有争议。</p>',9)),(n(),t(l,null,{default:o(()=>[s(A,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20MAC%5B%22%E5%AE%8F%E8%A7%82%E5%9F%BA%E6%9C%AC%E9%9D%A2%E6%85%A2%22%5D%20--%3E%20DIS%5B%22E%20%E6%B3%A2%E5%8A%A8%E5%A4%A7%E3%80%81%E9%A2%84%E6%8A%A5%E5%B7%AE%22%5D%0A%20%20MR%5B%22Meese%E2%80%93Rogoff%22%5D%20--%3E%20RW%5B%22%E6%B8%B8%E8%B5%B0%E8%B5%A2%E7%BB%93%E6%9E%84%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20PV%5B%22%E8%B5%84%E4%BA%A7%E7%8E%B0%E5%80%BC%20%2B%20%E8%BF%91%E5%8D%95%E4%BD%8D%E6%A0%B9%22%5D%20--%3E%20RW2%5B%22%E5%8F%AF%E4%BB%A5%E5%83%8F%E6%B8%B8%E8%B5%B0%22%5D%0A%20%20TC%5B%22%E8%B4%B8%E6%98%93%E6%88%90%E6%9C%AC%22%5D%20--%3E%20PUZ%5B%22%E5%80%99%E9%80%89%3A%20%E4%B8%80%E5%9D%97%E8%A7%A3%E9%87%8A%E5%A4%9A%E8%B0%9C%22%5D%0A"})]),fallback:o(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("p",null,"与 CIP：脱节主要是浮动名义汇率相对宏观；CIP 是短端复制，危机后基差是中介约束，对象不同，见量化栏。",-1)),E[4]||(E[4]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=e("p",null,[a("机制是汇率作为资产价格：对未来 \\(m\\)、\\(y\\)、政策的预期贴现。噪声、学习、微观流动性可以加大短期波动。货物市场慢（PTM、发票货币）使 \\(q\\) 持久偏离 PPP——主干"),e("a",{href:"/econ/ppp-loop"},"PPP"),a(" 已有环。脱节强调："),e("strong",null,"即使"),a("把这些写进模型，1970–80 年代的估计仍预报失败。后来的 Taylor 规则模型、贝叶斯 VAR 有时改善，但不取消谜的地位。")],-1)),E[6]||(E[6]=e("p",null,"与干预：官方可以暂时压波动，解释不了十年级的脱节。与 Lucas 批判：结构模型用旧制度系数预报新政后的 \\(E\\)，失败可以是批判而不是「汇率不可建模」。",-1)),E[7]||(E[7]=e("p",null,[e("span",{class:"marginnote"},"六谜不必有单一微观。主乡偏好与风险分担可以是市场不完全；FH 可以是跨期约束；脱节可以是贴现。Obstfeld–Rogoff 用贸易成本当候选统一，本课当菜单不是定论。")],-1)),(n(),t(l,null,{default:o(()=>[s(A,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E6%9C%AA%E6%9D%A5%E5%9F%BA%E6%9C%AC%E9%9D%A2%E8%B7%AF%E5%BE%84%3A%20%E8%B4%A7%E5%B8%81%2C%20%E4%BA%A7%E5%87%BA%2C%20%E6%94%BF%E7%AD%96%22%5D%20--%3E%20EXP%5B%22%E4%BB%8A%E5%A4%A9%E7%9A%84%20E%20%3D%20%E9%A2%84%E6%9C%9F%E7%9A%84%E8%B4%B4%E7%8E%B0%E5%92%8C%22%5D%0A%20%20EXP%20--%3E%20NEAR%5B%22%E8%B4%B4%E7%8E%B0%E5%9B%A0%E5%AD%90%E8%BF%91%201%20%2B%20%E5%9F%BA%E6%9C%AC%E9%9D%A2%E8%BF%91%E5%8D%95%E4%BD%8D%E6%A0%B9%22%5D%0A%20%20NEAR%20--%3E%20RW%5B%22%E6%B1%87%E7%8E%87%E8%BF%91%E4%BC%BC%E9%9A%8F%E6%9C%BA%E6%B8%B8%E8%B5%B0%22%5D%0A%20%20RW%20--%3E%20FC%5B%22%E7%BB%93%E6%9E%84%E6%A8%A1%E5%9E%8B%E9%9A%BE%E8%B5%A2%E6%B8%B8%E8%B5%B0%E9%A2%84%E6%8A%A5%22%5D%0A%20%20GOOD%5B%22%E8%B4%A7%E7%89%A9%E5%B8%82%E5%9C%BA%E6%85%A2%3A%20PTM%20%E4%B8%8E%E5%8F%91%E7%A5%A8%E8%B4%A7%E5%B8%81%22%5D%20--%3E%20QP%5B%22%E5%AE%9E%E9%99%85%E6%B1%87%E7%8E%87%E6%8C%81%E4%B9%85%E5%81%8F%E7%A6%BB%20PPP%22%5D%0A%20%20QP%20--%3E%20VOL%5B%22%E8%B5%84%E4%BA%A7%E7%AB%AF%E5%BF%AB%20%2B%20%E5%95%86%E5%93%81%E7%AB%AF%E6%85%A2%3A%20%E6%B3%A2%E5%8A%A8%E6%94%BE%E5%A4%A7%22%5D%0A"})]),fallback:o(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[8]||(E[8]=B('<p><span class="marginnote">数字实例：月度贴现因子取 0.99 时，权重每远一个月乘 0.99，衰减一半约需 69 个月——按几何权重算，一半以上的定价权重压在五年之外的预期上。这就是为什么今天的宏观观测「装不下」汇率的短期波动：价格早已把遥远的未来贴现进来了。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重做 1983 年的表。不把随机游走写成市场有效的证明——有效可以有风险溢价，溢价下一课。不要用高频订单流吞并宏观课。下一课远期溢价：UIP 回归的斜率之谜，是脱节家族里资产平价那一支。</p><p>后课默认：短期 \\(E\\) 相对宏观脱节，游走是苛刻基准；现值逻辑可部分和解预报，定量仍紧。PPP 长期、脱节短期，分层。UIP 偏差下一课专写。</p><p><span class="marginnote">常见误区：「游走预报最好 = 市场无效或汇率不可建模」。两步都跳太快：游走胜出只说明短期条件均值难测；而 Engel–West 表明，理性贴现加上持久的基本面，本身就足以让价格长得像游走——脱节与有效、与现值逻辑并不矛盾。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Meese–Rogoff：结构模型样本外打不赢游走。</li><li>脱节：宏观慢、汇率快；超调定性不够定量。</li><li>现值 + 持久基本面可以产生近游走。</li><li>六谜是一簇，贸易成本是候选不是判决。</li><li>出处：Meese and Rogoff, <em>JIE</em> 1983；Obstfeld and Rogoff, NBER Macro Annual 2000；Engel and West。</li></ul>',7))])}const C=r(f,[["render",p]]);export{g as __pageData,C as default};
